است که همهٔ اعضای~$A$ در آنها مشترک‌اند:
\begin{align*}
\bigcap A & = \Setabs{x}{x \text{ متعلق به هر !!{element} از } A},
\text{ یعنی}\\
 & = \Setabs{x}{\text{برای هر } B \in A, x \in B}
\end{align*}
\end{defn}

